const {test}=require('node:test'),assert=require('node:assert/strict'),path=require('node:path');
const root=path.resolve(__dirname,'../..'),extensions=require('../../core/extensions.cjs');
test('both native shells are discovered without a panel allowlist',()=>{const shells=extensions.catalog(root).shells;assert.deepEqual(shells.errors,[]);assert.deepEqual(shells.items.map(s=>s.id).sort(),['izlauncher','izpslauncher']);});
for(const id of ['izlauncher','izpslauncher'])test(id+' has matching compiled app metadata and a usable native lifecycle',async()=>{const shell=extensions.catalog(root).shells.items.find(s=>s.id===id),app=await require('../../core/services/app-catalog.cjs').readApp(path.join(shell.folder,'app'));assert.equal(app.id,id);assert.equal(shell.version,require('../../package.json').version);assert.equal(app.version,shell.version);const pin=await extensions.pin(root,'shell',id),factory=pin.load();assert.equal(await factory.compatible({modes:['izlauncher']}),true);assert.equal(await factory.compatible({modes:['original']}),false);const instance=await factory.create({root});await assert.rejects(instance.init(),/Qualified native session/);await instance.dispose();});
